local config = {
  ui_story_5034_50340000_1_dialog_content = "<color=#e8d9bb>¡Choque!</color>",
  ui_story_5034_50340000_2_dialog_content = "¡Oh, no! ¿Estás bien?",
  ui_story_5034_50340000_3_dialog_content = "Estoy bien...",
  ui_story_5034_50340000_4_dialog_content = "¿Eh? ¡Es usted, Sr. Navegante!",
  ui_story_5034_50340000_5_dialog_content = "Oh, hola, <color=#FFB400>Schewe</color>.",
  ui_story_5034_50340000_6_dialog_content = "Sabes que puedes llamarme por mi nombre, ¿verdad? Como lo hacen Nekoyashiki y los demás.",
  ui_story_5034_50340000_7_dialog_content = "¿Qué? ¡De ninguna manera!",
  ui_story_5034_50340000_8_dialog_content = "¡Eres mayor que yo y tengo que respetar a mis mayores!",
  ui_story_5034_50340000_9_dialog_content = "Eh... Está bien, entonces.",
  ui_story_5034_50340000_10_dialog_content = "¿Qué te pareció el caramelo? ¿Sabía bien?",
  ui_story_5034_50340000_11_dialog_content = "¡Por supuesto! ¡Fue absolutamente delicioso!",
  ui_story_5034_50340000_12_dialog_content = "¡Es nuestro dulce favorito! ¡Gracias, Sr. Navegante!",
  ui_story_5034_50340000_13_dialog_content = "¡Schewe está mintiendo! ¡No se lo comió en absoluto!",
  ui_story_5034_50340000_14_dialog_content = "¡Latán! ¡El Sr. Navigator y yo estamos hablando, vete!",
  ui_story_5034_50340000_15_dialog_content = "¡Pero mentiste, Schewe! Tú me diste los dulces...",
  ui_story_5034_50340000_16_dialog_content = "¿Recuerdas lo que nos dijo Pólux? ¡No debemos mentirle a la gente que es amable con nosotros!",
  ui_story_5034_50340000_17_dialog_content = "No quise mentir, ¡ahora vete!",
  ui_story_5034_50340000_18_dialog_content = "Schewe... ¿Me pediste ese dulce para que Latan se sintiera mejor?",
  ui_story_5034_50340000_19_dialog_content = "Supongo que no hay manera de pasar por su lado, Sr. Navegante. Lo siento, no debí haber mentido en primer lugar.",
  ui_story_5034_50340000_20_dialog_content = "¿Sr. Navegante? Realmente quiero que Schewe también tenga algunos dulces.",
  ui_story_5034_50340000_21_dialog_content = "Si hubiera sabido que solo había un trozo, no me lo habría comido todo de un bocado...",
  ui_story_5034_50340000_22_dialog_content = "No seas una molestia, Latan. Estoy bien sin",
  ui_story_5034_50340000_23_dialog_content = "¡Solo verte de vuelta a tu antiguo yo me hace sentir más feliz que comer cualquier dulce!",
  ui_story_5034_50340000_24_dialog_content = "Muy bien, chiquillos. Eso servirá por ahora.",
  ui_story_5034_50340000_25_dialog_content = "Es solo un caramelo, ¿sabes? Comprar dulces no es gran cosa para alguien adulto como yo.",
  ui_story_5034_50340000_26_dialog_content = "Pero solo Nekoyashiki tiene ese tipo de dulces... No podemos encontrarlos en Euphoria en absoluto.",
  ui_story_5034_50340000_27_dialog_content = "Si Nekoyashiki puede conseguirlo de alguna manera, ¿por qué yo no? ¡Denme un poco de crédito, muchachos!",
  ui_story_5034_50340000_28_dialog_content = "¡Solo espera, te traeré tantos dulces que no podrás terminarlos todos!",
  ui_story_5034_50340000_29_dialog_content = "¡Hurra! ¡Eres el mejor, Sr. Navegante! ¡Nadie es más amable que tú!",
  ui_story_5034_50340000_30_dialog_content = "Oye, Latan, no digas eso...",
  ui_story_5034_50340000_31_dialog_content = "¿Qué pasa si el Sr. Navigator no puede encontrar los dulces?",
  ui_story_5034_50340000_32_dialog_content = "Gracias por el voto de confianza, Schewe...",
  ui_story_5034_50340000_33_dialog_content = "De todos modos, los adultos siempre deben cumplir sus promesas a los niños. Ustedes dos esperen aquí por mí, y volveré pronto.",
  ui_story_5034_50340000_34_dialog_content = "(Ahora, ¿dónde debo ir a buscar ese dulce...?)",
  ui_story_5034_50340000_35_dialog_content = "(¡Oh, sí! ¡Apuesto a que ella tendría alguna idea!)",
  ui_story_5034_50340000_36_dialog_content = "¿Mmm? Ya me siento descansado, ya veo?",
  ui_story_5034_50340000_37_dialog_content = "¡Definitivamente! Me siento perfectamente bien ahora.",
  ui_story_5034_50340000_38_dialog_content = "Por cierto, Pólux... Hay algo que me gustaría preguntarte.",
  ui_story_5034_50340000_39_dialog_content = "¿Sabes dónde puedo encontrar más de esos dulces que les gustan a los niños?",
  ui_story_5034_50340000_40_dialog_content = "Estás hablando de los dulces que suele traer Nekoyashiki, ¿no?",
  ui_story_5034_50340000_41_dialog_content = "No lo he visto en ningún lugar de Euphoria, lo que significa que debe traerlo de algún otro lugar.",
  ui_story_5034_50340000_42_dialog_content = "Pero, ¿por qué no vas y le preguntas tú mismo? No creo que se haya ido todavía.",
  ui_story_5034_50340000_43_option_content = "¡De ninguna manera!",
  ui_story_5034_50340000_44_dialog_content = "Además, son solo dulces. Si él puede conseguirlo, entonces yo también.",
  ui_story_5034_50340000_45_dialog_content = "¡Mientras no lo haga él mismo, estoy seguro de que puedo encontrar una manera de comprar algo!",
  ui_story_5034_50340000_46_option_content = "Parece que no tengo más remedio que preguntarle...",
  ui_story_5034_50340000_47_dialog_content = "¿Realmente no hay otra manera...?",
  ui_story_5034_50340000_48_dialog_content = "Gracias Pólux.",
  ui_story_5034_50340000_49_dialog_content = "Esperar, PlayerName. Acabo de recordar cierta tienda en la ciudad que ha estado en el negocio durante mucho tiempo.",
  ui_story_5034_50340000_50_dialog_content = "El comerciante es muy hábil en los negocios y trae todo tipo de productos exóticos para vender aquí en Euphoria.",
  ui_story_5034_50340000_51_dialog_content = "Es posible que desee probar suerte allí primero.",
  ui_story_5034_50340000_52_dialog_content = "¡Entiendo! ¡Gracias de nuevo, Pólux!",
  ui_story_5034_50340000_53_dialog_content = "¡Oye! ¡Aún no te he dicho dónde está la tienda!",
  ui_story_5034_50340000_54_dialog_content = "Siempre con tanta prisa...",
  ui_story_5034_50340000_55_dialog_content = "Corax! ¿Dónde estás, Corax?",
  ui_story_5034_50340000_56_dialog_content = "Justo detrás de ti... ¿Qué pasa con todos los gritos?",
  ui_story_5034_50340000_57_dialog_content = "¡Ahhh! ¡No me acerques así!",
  ui_story_5034_50340000_58_dialog_content = "De todos modos, ¿tienes un minuto, Corax?",
  ui_story_5034_50340000_59_dialog_content = "¿Por qué preguntas?",
  ui_story_5034_50340000_60_dialog_content = "Quiero comprar unos dulces, pero la tienda que los vende está en el pueblo, y no quiero ir solo...",
  ui_story_5034_50340000_61_dialog_content = "No puedo ayudarte. Me voy a un lugar agradable y vacío para alimentar a los pájaros.",
  ui_story_5034_50340000_62_dialog_content = "¿Eh? ¿Soy realmente menos importante que un par de pájaros?",
  ui_story_5034_50340000_63_dialog_content = "Oh, hola, Nekoyashiki. Llegas justo a tiempo.",
  ui_story_5034_50340000_64_dialog_content = "PlayerName quiere ir al pueblo a comprar dulces. Ve con él, ¿quieres? No tengo tiempo para eso.",
  ui_story_5034_50340000_65_dialog_content = "corax...",
  ui_story_5034_50340000_66_dialog_content = "Ah... Candy, dices?",
  ui_story_5034_50340000_67_dialog_content = "Así que ese dulce que te di antes... Te lo comiste tú mismo en lugar de dárselo a los niños, ¿no?",
  ui_story_5034_50340000_68_dialog_content = "No sabía que ese era el tipo de persona que eras, PlayerName...",
  ui_story_5034_50340000_69_dialog_content = "¡No dejes volar tu imaginación! Solo quería comprar más para los niños, eso es todo.",
  ui_story_5034_50340000_70_dialog_content = "Pero como ya estás aquí, me ahorra la molestia de ir a la ciudad.",
  ui_story_5034_50340000_71_dialog_content = "Si tienes más de esos dulces, ¿por qué no me los vendes todos?",
  ui_story_5034_50340000_72_dialog_content = "Me encantaría ayudarte a lucir genial frente a los niños, PlayerName...",
  ui_story_5034_50340000_73_dialog_content = "Pero desafortunadamente, ya he repartido o comido el resto de los dulces.",
  ui_story_5034_50340000_74_dialog_content = "Esa pieza que te di resultó ser la última.",
  ui_story_5034_50340000_75_dialog_content = "De verdad... Parece que tendré que probar suerte en esa tienda, después de todo...",
  ui_story_5034_50340000_76_dialog_content = "\"Esa tienda\"?",
  ui_story_5034_50340000_77_dialog_content = "No tenía idea de que había una tienda en Euphoria que vendiera este tipo de dulces... Ahora tengo mucha curiosidad por verlo yo mismo.",
  ui_story_5034_50340000_78_dialog_content = "Le pregunté a Pollux y me habló de una tienda en la ciudad que importa todo tipo de productos exóticos. Voy a ver si lo encuentro por ahí.",
  ui_story_5034_50340000_79_dialog_content = "<size=30>Ah... esa tienda...</size>",
  ui_story_5034_50340000_80_dialog_content = "Mierda, espera un minuto... Me olvidé por completo de preguntarle a Pollux dónde está.",
  ui_story_5034_50340000_81_dialog_content = "Me pregunto si todavía estará en la entrada...",
  ui_story_5034_50340000_82_dialog_content = "Yo sé donde está. Vamos, te llevaré allí.",
  ui_story_5034_50340000_83_dialog_content = "Qué...? ¿vas conmigo?",
  ui_story_5034_50340000_84_dialog_content = "Solo tengo curiosidad por ver si el comerciante tiene lo que se necesita para conseguir este tipo de dulces, eso es todo.",
  ui_story_5034_50340000_85_dialog_content = "Da la casualidad de que vamos en la misma dirección.",
  ui_story_5034_50340000_86_dialog_content = "Ahora date prisa, o me iré solo.",
  ui_story_5034_50340000_87_dialog_content = "¡Oye! ¡Espérame!",
  ui_story_5034_50340101_1_dialog_content = "Deberíamos llegar pronto, ¿verdad? Se siente como si hubiéramos estado caminando por siempre...",
  ui_story_5034_50340101_2_dialog_content = "Sí... Si no me equivoco, entonces esta debería ser la tienda de la que hablaba Pólux.",
  ui_story_5034_50340101_3_dialog_content = "Vamos, entremos y echemos un vistazo.",
  ui_story_5034_50340101_4_dialog_content = "Bueno, si no es Nekoyashiki... ¿A qué debo el placer de un cliente tan raro?",
  ui_story_5034_50340101_5_dialog_content = "Nunca pensé que una humilde tienda como la mía pudiera tener algo de interés para alguien como tú.",
  ui_story_5034_50340101_6_dialog_content = "Oh, no me hagas caso, solo estoy echando un vistazo... Él, por otro lado, está interesado en comprar algo.",
  ui_story_5034_50340101_7_dialog_content = "Disculpe, pero ¿vende dulces aquí?",
  ui_story_5034_50340101_8_dialog_content = "Tendrás que buscarlo tú mismo. Además, no vendemos nada a crédito, así que no se moleste en preguntar.",
  ui_story_5034_50340101_9_dialog_content = "Alguien se levantó del lado equivocado de la cama...",
  ui_story_5034_50340101_10_dialog_content = "No importa, no me importa mirar por mi cuenta.",
  ui_story_5034_50340101_11_dialog_content = "¡Ay! ¡Lo encontré! ¡No puedo creer que esté realmente en stock aquí!",
  ui_story_5034_50340101_12_dialog_content = "¿Hmm? Dejame ver eso...",
  ui_story_5034_50340101_13_dialog_content = "¿Vaya? Oiga, tendero... ¿De dónde exactamente importó esto?",
  ui_story_5034_50340101_14_dialog_content = "Tratando de sacarme del negocio, ¿eh? Ya tiene muchos canales para sus productos, así que no es necesario que le cuente sobre el mío, muchas gracias.",
  ui_story_5034_50340101_15_dialog_content = "Dirigir incluso una pequeña tienda como la mía no es fácil, ¿sabes? Trate de pensar en las personitas de vez en cuando, \"Maestro\" Nekoyashiki.",
  ui_story_5034_50340101_16_dialog_content = "Si el negocio es tan difícil, ¿por qué importaría un dulce impopular como este? ¿No le preocupa perder sus ganancias?",
  ui_story_5034_50340101_17_dialog_content = "Noté que a los niños aquí les gusta este dulce. Si no puedo venderlos, se los daré a los niños.",
  ui_story_5034_50340101_18_dialog_content = "Ah, ya veo...",
  ui_story_5034_50340101_19_dialog_content = "¿Mirarías eso? Supongo que no eres el único que lleva ese tipo de dulces ahora, ¿eh?",
  ui_story_5034_50340101_20_dialog_content = "Parece tan... Bueno, las felicitaciones están en orden, supongo.",
  ui_story_5034_50340101_21_dialog_content = "¡Me lo llevaré todo, señor!",
  ui_story_5034_50340101_22_dialog_content = "¡Espléndido! Ahora bien, son 3.000 Nightium por bolsa, para un total de...",
  ui_story_5034_50340101_23_dialog_content = "¡Espera un segundo! ¡¿Dijiste 3,000 Nightium por bolsa?!",
  ui_story_5034_50340101_24_dialog_content = "*Riendo*",
  ui_story_5034_50340101_25_dialog_content = "Pues sí, eso es lo que dije. Cada bolsa de este caramelo en particular cuesta 3000 Nightium.",
  ui_story_5034_50340101_26_dialog_content = "Pero si compras todas mis acciones, te enviaré una bolsa grande para que las lleves a casa.",
  ui_story_5034_50340101_27_dialog_content = "Pero, para empezar, ¿cómo una sola bolsa de caramelos podía costar 3000 Nightium?",
  ui_story_5034_50340101_28_dialog_content = "Nekoyashiki, ¡¿qué tan rico eres?!",
  ui_story_5034_50340101_29_dialog_content = "Nunca dije que compré mis dulces aquí.",
  ui_story_5034_50340101_30_dialog_content = "Entonces lo que estás diciendo... es que este tipo me está estafando, ¿verdad?",
  ui_story_5034_50340101_31_dialog_content = "Euphoria no tiene los medios para producir dulces, entre otras cosas. La mayoría de los productos se importan aquí a través de rutas comerciales establecidas.",
  ui_story_5034_50340101_32_dialog_content = "Como resultado, la mayoría de las cosas que encuentras a la venta aquí son más caras que en otros lugares.",
  ui_story_5034_50340101_33_dialog_content = "¿Me estás diciendo que 3,000 Nightium por una mísera bolsa de dulces es aceptable para ti entonces?",
  ui_story_5034_50340101_34_dialog_content = "Eso no es lo que yo dije. Simplemente le estoy dando algunos antecedentes para que se sienta mejor cuando haga sus compras.",
  ui_story_5034_50340101_35_dialog_content = "<size=45>Eso no ayuda en absoluto.</size>",
  ui_story_5034_50340101_36_dialog_content = "Eres más que bienvenido a comprar bolsas individuales de dulces, si quieres. Por supuesto, la bolsa de mano estará fuera de discusión...",
  ui_story_5034_50340101_37_dialog_content = "(Supongo que no tengo otra opción. Les prometí a los niños después de todo... 3000 Nightium por bolsa, debería poder pagar al menos uno... ¿Verdad?)",
  ui_story_5034_50340101_38_dialog_content = "Yo... solo tengo 150 Nightium conmigo.",
  ui_story_5034_50340101_39_dialog_content = "No me mires, traigo mi cabeza cuando salgo de casa, no mi dinero.",
  ui_story_5034_50340101_40_dialog_content = "Si tan solo estuviéramos en Umbraton... ¡Podría conseguir al menos cinco bolsas de caramelos por 150 Nightium!",
  ui_story_5034_50340101_41_dialog_content = "¿Aquí nadie hace nada por estos precios exorbitantes?",
  ui_story_5034_50340101_42_dialog_content = "Pero no estamos en Umbraton, ¿verdad? Estamos en Euphoria, así que tienes que seguir las reglas de Euphoria.",
  ui_story_5034_50340101_43_dialog_content = "Y no olvides, amigo mío, que en esta tienda no vendemos nada a crédito.",
  ui_story_5034_50340101_44_dialog_content = "Si no vas a comprar nada, devolveré estas cosas a los estantes.",
  ui_story_5034_50340101_45_dialog_content = "(Si no encuentro la manera de recuperar estos dulces, Schewe y Latan se sentirán muy decepcionados).",
  ui_story_5034_50340101_46_dialog_content = "(Y después de todo lo que dije, también...)",
  ui_story_5034_50340101_47_dialog_content = "Me gustaría comprar una bolsa, señor... Pero realmente no tengo suficiente dinero conmigo.",
  ui_story_5034_50340101_48_dialog_content = "¿Quizás pueda cambiar algo por una bolsa?",
  ui_story_5034_50340101_49_dialog_content = "Ya veo... Bueno, no me gustaría rechazar a un amigo de Nekoyashiki tan groseramente.",
  ui_story_5034_50340101_50_dialog_content = "¿Cómo es esto? ¿Por qué no te quedas un rato y trabajas para mí, y te doy esa bolsa de dulces como pago por tu ayuda? ¿Suena justo?",
  ui_story_5034_50340101_51_dialog_content = "¡Suena como un trato! Entonces, ¿qué es exactamente lo que necesitas que haga?",
  ui_story_5034_50340101_52_dialog_content = "No puedo decir que tenga mucha experiencia laboral, pero prometo que soy uno de los mejores en Astra.",
  ui_story_5034_50340101_53_dialog_content = "Debería irme ahora. Mucha suerte, <color=#FFB400>trabajador a tiempo parcial</color>.",
  ui_story_5034_50340102_1_dialog_content = "(Cuando finalmente miré el reloj, casi había pasado una mañana entera).",
  ui_story_5034_50340102_2_dialog_content = "(Almacenar y organizar estantes, barrer la tienda... Incluso quería que atrajera clientes).",
  ui_story_5034_50340102_3_dialog_content = "(¿Pero quién compraría en una tienda con precios tan locos?)",
  ui_story_5034_50340102_4_dialog_content = "Bueno, joven?",
  ui_story_5034_50340102_5_dialog_content = "Ahora sabes lo difícil que es administrar una tienda en Euphoria.",
  ui_story_5034_50340102_6_dialog_content = "Aun así, no quisiera ponerle las cosas difíciles a un amigo de Nekoyashiki...",
  ui_story_5034_50340102_7_dialog_content = "(¿Estás bromeando? ¡Estoy bastante seguro de que estás haciendo esto PRECISAMENTE porque lo conozco!)",
  ui_story_5034_50340102_8_dialog_content = "(No hace falta decirlo, ¡pero nunca más volveré a esta tienda!)",
  ui_story_5034_50340102_9_dialog_content = "Aquí tienes, entonces, una bolsa de dulces como pago por tu arduo trabajo.",
  ui_story_5034_50340102_10_dialog_content = "No estoy seguro si debería agradecerte o no...",
  ui_story_5034_50340102_11_dialog_content = "No es necesario dar las gracias... Pero trate de recordar traer más dinero la próxima vez.",
  ui_story_5034_50340102_12_dialog_content = "Oh, no tienes que preocuparte por eso... ¡definitivamente no habrá una próxima vez!",
  ui_story_5034_50340102_13_dialog_content = "En cualquier caso, al menos conseguí los dulces.",
  ui_story_5034_50340102_14_dialog_content = "Es solo una bolsa, pero lo tengo. ¡Ahora Schewe también puede disfrutar un poco!",
  ui_story_5034_50340102_15_dialog_content = "¿Mmm? Un momento, hay algo impreso en la bolsa...",
  ui_story_5034_50340102_16_dialog_content = "\"Producido por Far Eastern Specialties en Umbraton...\"",
  ui_story_5034_50340102_17_dialog_content = "\"Precio de venta sugerido: 30 Nightium...\"",
  ui_story_5034_50340102_18_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_5034_50340102_19_dialog_content = "Me esclavicé toda la mañana para comprar una bolsa de caramelos de 3000 Nightium, pero después de todo eso...",
  ui_story_5034_50340102_20_dialog_content = "<size=45>¿Todo el tiempo solo fueron caramelos baratos de Umbraton?</size>",
  ui_story_5034_50340102_21_dialog_content = "¿Mirarías eso? Supongo que no eres el único que lleva ese tipo de dulces ahora, ¿eh?",
  ui_story_5034_50340102_22_dialog_content = "Parece tan... Bueno, las felicitaciones están en orden, supongo.",
  ui_story_5034_50340102_23_dialog_content = "¡Él sabía! ¡Él lo sabía, pero no se molestó en decírmelo!",
  ui_story_5034_50340102_24_dialog_content = "<color=#e8d9bb>*Refunfuñando*</color>",
  ui_story_5034_50340102_25_dialog_content = "Ugh... me muero de hambre después de todo ese trabajo duro...",
  ui_story_5034_50340102_26_dialog_content = "Es casi mediodía. Si me apresuro a volver, debería poder llegar a tiempo para el almuerzo con los niños.",
  ui_story_5034_50340102_27_dialog_content = "Dejaré que ese comerciante corrupto salga libre por ahora... Entregar estos dulces a los niños es mucho más importante en este momento.",
  ui_story_5034_50340102_28_dialog_content = "Pero recuerda mis palabras, la próxima vez que lo vea... ¡Le daré una pequeña lección sobre el comercio justo!",
  ui_story_5034_50340102_29_dialog_content = "¡Mira, Schewe! ¡El Sr. Navigator realmente logró encontrar algunos de esos dulces!",
  ui_story_5034_50340102_30_dialog_content = "¡Tú también podrás probar algunos!",
  ui_story_5034_50340102_31_dialog_content = "Pero trabajó duro toda la mañana por ese dulce...",
  ui_story_5034_50340102_32_dialog_content = "Eso es verdad... Seguimos al Sr. Navegante porque queríamos ver de dónde sacaba los dulces.",
  ui_story_5034_50340102_33_dialog_content = "Dijo que también nos iba a comprar lotes...",
  ui_story_5034_50340102_34_dialog_content = "Sabía que no lo decía en serio.",
  ui_story_5034_50340102_35_dialog_content = "Pero si tan solo no hubiéramos parecido tan desesperados por comer los dulces...",
  ui_story_5034_50340102_36_dialog_content = "Él no habría tenido que trabajar para ese comerciante malvado solo para comprárnoslo.",
  ui_story_5034_50340102_37_dialog_content = "Me equivoqué, Latan... No merezco comerme los dulces...",
  ui_story_5034_50340102_38_dialog_content = "Schewe...",
  ui_story_5034_50340102_39_dialog_content = "¡Esperar! ¡Tengo una idea!",
  ui_story_5034_50340102_40_dialog_content = "Una idea...?",
  ui_story_5034_50340102_41_dialog_content = "Si el Sr. Navigator pudo trabajar en esa tienda, ¡nosotros también podemos!",
  ui_story_5034_50340102_42_dialog_content = "¿Quieres decir que podemos trabajar por los dulces también?",
  ui_story_5034_50340102_43_dialog_content = "¡Así es! ¡De esa manera, el Sr. Navegante no pensará que somos solo un par de niños egoístas!",
  ui_story_5034_50340102_44_dialog_content = "No podemos quedarnos aquí y esperar a que nos traiga dulces.",
  ui_story_5034_50340102_45_dialog_content = "¡Él también merece disfrutar de los frutos de nuestro arduo trabajo!",
  ui_story_5034_50340102_46_dialog_content = "¡Y con nosotros dos, deberíamos poder ganar dos bolsas en lugar de una! Pero, ¿qué debemos hacer con la segunda bolsa?",
  ui_story_5034_50340102_47_dialog_content = "¿Por qué no dárselo a Pólux como regalo? Ella también trabaja duro para cuidarnos... ¡Deberíamos mostrarle nuestra gratitud!",
  ui_story_5034_50340102_48_dialog_content = "¡Entonces está resuelto! En cuanto a esa persona que odia los dulces, Casta... ¿Deberíamos usar nuestro <color=#FFB400>truco habitual</color>?",
  ui_story_5034_50340102_49_dialog_content = "Bueno, esto no será fácil, Latan.",
  ui_story_5034_50340102_50_dialog_content = "¡Lo sé! ¡Sólo déjamelo a mi!",
  ui_story_5034_50340201_1_dialog_content = "Oh, estás de vuelta.",
  ui_story_5034_50340201_2_dialog_content = "¿Pensé que saliste solo a comprar dulces? ¿Por qué estás tan sudado?",
  ui_story_5034_50340201_3_dialog_content = "\"Solo para conseguir dulces\", mi trasero...",
  ui_story_5034_50340201_4_dialog_content = "¿Has visto a Nekoyashiki? Necesito \"agradecerle\" apropiadamente por ayudarme.",
  ui_story_5034_50340201_5_dialog_content = "No lo he visto por aquí. ¿No se fueron ustedes dos juntos?",
  ui_story_5034_50340201_6_dialog_content = "<color=#e8d9bb>*Refunfuñando*</color>",
  ui_story_5034_50340201_7_dialog_content = "Ah... Tanta hambre... Supongo que lo dejaré en paz por ahora.",
  ui_story_5034_50340201_8_dialog_content = "¿Ya está listo el almuerzo? ¿Qué tenemos hoy?",
  ui_story_5034_50340201_9_dialog_content = "Lo siento, pero todos terminaron de almorzar hace un rato.",
  ui_story_5034_50340201_10_dialog_content = "¡¿Qué?! ¡¿Y nadie pensó en dejarme algo?!",
  ui_story_5034_50340201_11_dialog_content = "Tienes una bolsa de dulces en la mano, ¿no? Solo come unas cuantas piezas y te aguantará hasta la cena.",
  ui_story_5034_50340201_12_dialog_content = "¡No se puede hacer, este dulce es para Schewe y Latan, así como para los otros niños!",
  ui_story_5034_50340201_13_dialog_content = "No tienes idea de lo que pasé por esta bolsa de dulces...",
  ui_story_5034_50340201_14_dialog_content = "Hablando de eso... ¿dónde están Schewe y Latan?",
  ui_story_5034_50340201_15_dialog_content = "¿Sabes dónde están esos dos, Corax?",
  ui_story_5034_50340201_16_dialog_content = "Te refieres a los dos niños que estaban pidiendo dulces, ¿sí?",
  ui_story_5034_50340201_17_dialog_content = "¡Sí, esos dos!",
  ui_story_5034_50340201_18_dialog_content = "Te siguieron hasta la ciudad, si mal no recuerdo.",
  ui_story_5034_50340201_19_dialog_content = "¿Esperar lo? ¿Por qué me seguían?",
  ui_story_5034_50340201_20_dialog_content = "Después de que te fuiste de la iglesia temprano esta mañana, esos dos también se fueron poco después.",
  ui_story_5034_50340201_21_dialog_content = "Pensé que todos viajaban en grupo... ¿Significa eso que nunca los vieron mientras estaban en la ciudad?",
  ui_story_5034_50340201_22_dialog_content = "Yo no... No tenía idea de que me seguían. Pero ya he regresado, entonces, ¿dónde podrían estar?",
  ui_story_5034_50340201_23_dialog_content = "No te asustes, estoy seguro de que están donde sea que hayas ido por última vez.",
  ui_story_5034_50340201_24_dialog_content = "¡Estás bien! ¡Debería volver y buscarlos!",
  ui_story_5034_50340201_25_dialog_content = "¡Ya vuelvo, Corax! Vigila a los otros niños por mí, ¿quieres?",
  ui_story_5034_50340201_26_dialog_content = "¡Oye! ¡Toma esto también!",
  ui_story_5034_50340201_27_dialog_content = "¿Esto es... <color=#FFB400>media hogaza de pan</color>?",
  ui_story_5034_50340201_28_dialog_content = "Es un poco rancio, pero tendrá que ser suficiente.",
  ui_story_5034_50340201_29_dialog_content = "Si dejo que el último Caelestite del mundo muera de hambre, tendré que pasar el resto de mi vida en Euphoria.",
  ui_story_5034_50340201_30_dialog_content = "Gracias, Corax... ¡Saborearé cada bocado!",
  ui_story_5034_50340201_31_dialog_content = "(Schewe, Latan... ¡Estoy en camino! Solo espero que no les haya pasado nada malo...)",
  ui_story_5034_50340202_1_dialog_content = "No me di cuenta de su presencia en absoluto...",
  ui_story_5034_50340202_2_dialog_content = "¿No me digas que están en la tienda?",
  ui_story_5034_50340202_3_dialog_content = "¡Se venden gafas de sol!",
  ui_story_5034_50340202_4_dialog_content = "¡El estilo más nuevo, directo de Umbraton!",
  ui_story_5034_50340202_5_dialog_content = "¿Mmm? Esa voz suena terriblemente familiar...",
  ui_story_5034_50340202_6_dialog_content = "¿Hey señor? ¿Puedo interesarte en un par de gafas de sol?",
  ui_story_5034_50340202_7_dialog_content = "¡Están de moda en Umbraton!",
  ui_story_5034_50340202_8_dialog_content = "¿Ah?",
  ui_story_5034_50340202_9_dialog_content = "¿Estás diciendo que parezco el tipo de persona que necesita anteojos de sol?",
  ui_story_5034_50340202_10_dialog_content = "¿Algo está mal con la forma en que se ven mis ojos?",
  ui_story_5034_50340202_11_dialog_content = "¡N-En absoluto, señor! No quise decir eso...",
  ui_story_5034_50340202_12_dialog_content = "Je... Sabes, ver a un pipsqueak como tú trabajando me recuerda a mí mismo cuando era un niño.",
  ui_story_5034_50340202_13_dialog_content = "Muy bien chico, no digas que nunca hice nada bueno por ti. Cuanto por las sombras?",
  ui_story_5034_50340202_14_dialog_content = "Eh... 6.000 Nightium el par...",
  ui_story_5034_50340202_15_dialog_content = "¿Eh? Tienes agallas, pequeña... ¡Intentar engañar a la gente para que compre gafas de sol a ese precio es exactamente el tipo de cosas que hacía cuando era niña!",
  ui_story_5034_50340202_16_dialog_content = "Desafortunadamente, elegiste a la persona equivocada para meterte hoy. Déjame darte una muestra del mundo real...",
  ui_story_5034_50340202_17_dialog_content = "*sollozando*",
  ui_story_5034_50340202_18_dialog_content = "¿Latán? ¿Eres tu?",
  ui_story_5034_50340202_19_dialog_content = "M-Sr. ¡Navegador!",
  ui_story_5034_50340202_20_dialog_content = "*sollozando* estoy aquí...",
  ui_story_5034_50340202_21_dialog_content = "¡Muchacho, será mejor que te ocupes de tus propios asuntos!",
  ui_story_5034_50340202_22_dialog_content = "¿Qué pasa si no lo haré?",
  ui_story_5034_50340202_23_dialog_content = "Una charla bastante dura, para alguien que está solo...",
  ui_story_5034_50340202_24_dialog_content = "¿Quién dice que estoy solo?",
  ui_story_5034_50340202_25_dialog_content = "¡Por aquí, Corax! ¡Pólux!",
  ui_story_5034_50340202_26_dialog_content = "¿Qué? ¡¿Esa loca también está aquí?!",
  ui_story_5034_50340202_27_dialog_content = "¡J-Solo espera, punk! ¡Te atraparé la próxima vez!",
  ui_story_5034_50340202_28_dialog_content = "PlayerName... ¿El Sr. Corax también está contigo?",
  ui_story_5034_50340202_29_dialog_content = "¿No se supone que debería estar cuidando a los otros niños en la iglesia ahora?",
  ui_story_5034_50340202_30_dialog_content = "Lo siento, Latan... Justo ahora estaba fanfarroneando para asustar a ese tipo. Corax no está aquí en absoluto.",
  ui_story_5034_50340202_31_dialog_content = "Si el Sr. Corax estuviera aquí, no tendríamos que tener tanto miedo de ese <color=#FFB400>comerciante</color>...",
  ui_story_5034_50340202_32_dialog_content = "(\"¿Tendero\"? ¿Podría estar hablando de ESE tendero?)",
  ui_story_5034_50340202_33_dialog_content = "De todos modos, ¿qué está pasando aquí, Latan? ¿Por qué te estaba molestando ese tipo hace un momento?",
  ui_story_5034_50340202_34_dialog_content = "¿Y dónde está Schewe? no lo veo por ningun lado...",
  ui_story_5034_50340202_35_dialog_content = "Le diré lo que estoy haciendo más tarde, Sr. Navegante. En cuanto a Schewe, está dentro de la tienda.",
  ui_story_5034_50340202_36_dialog_content = "En el que compraste los dulces hoy temprano...",
  ui_story_5034_50340202_37_dialog_content = "Entiendo. No te preguntaré por qué me seguiste por el momento.",
  ui_story_5034_50340202_38_dialog_content = "Vamos a buscar a Schewe primero, ¿de acuerdo?",
  ui_story_5034_50340202_39_dialog_content = "¡De acuerdo!",
  ui_story_5034_50340202_40_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5034_50340202_41_dialog_content = "Tirando mis mercancías al suelo otra vez, ¿verdad? Tendré que añadir eso a tu deuda también.",
  ui_story_5034_50340202_42_dialog_content = "Honestamente... Viniste aquí a trabajar por algo de dinero, pero lo único que hiciste fue acumular deudas.",
  ui_story_5034_50340202_43_dialog_content = "Si ni siquiera puede reabastecer mis estantes correctamente, le sugiero que lo deje.",
  ui_story_5034_50340202_44_dialog_content = "De lo contrario, ¡tendrás cincuenta años antes de pagar tus deudas! Jajajaja!",
  ui_story_5034_50340202_45_dialog_content = "Yo... puedo hacerlo...",
  ui_story_5034_50340202_46_dialog_content = "<size=45>¡Ah!</size>",
  ui_story_5034_50340202_47_dialog_content = "<color=#e8d9bb>¡Clang-Clang!</color>",
  ui_story_5034_50340202_48_dialog_content = "Schewe!",
  ui_story_5034_50340202_49_dialog_content = "¡¿Estás bien?!",
  ui_story_5034_50340202_50_dialog_content = "Estoy bien, Sr. Navegante... Pero se me cayó otra caja, así que el comerciante la agregará a mi deuda otra vez...",
  ui_story_5034_50340202_51_dialog_content = "¿Deuda? ¿Qué diablos está pasando aquí?",
  ui_story_5034_50340202_52_dialog_content = "Bueno, bueno, bueno... Si no es el Sr. \"No voy a volver nunca más\", regresa mucho antes de lo esperado.",
  ui_story_5034_50340202_53_dialog_content = "Si quieres saberlo, este niño me debe mucho dinero por todos los problemas que me ha causado.",
  ui_story_5034_50340202_54_dialog_content = "...",
  ui_story_5034_50340202_55_dialog_content = "Si ese es el caso, entonces arreglemos las cosas de nuestra \"transacción\" anterior, ¿de acuerdo?",
  ui_story_5034_50340301_1_dialog_content = "Muy bien. Ya que usted es un cliente anterior, estoy más que feliz de hacerlo. ¿Le gustaría que le explique cómo surgió esta deuda?",
  ui_story_5034_50340301_2_dialog_content = "No gracias, creo que lo escucharé de estos dos, en su lugar.",
  ui_story_5034_50340301_3_dialog_content = "Schewe, Latan... ¿Pueden decirme exactamente qué está pasando aquí? No te preocupes, no estás en problemas.",
  ui_story_5034_50340301_4_option_content = "¿Puedes decirme por qué me seguiste?",
  ui_story_5034_50340301_5_dialog_content = "Lo siento, Sr. Navegante... Solo queríamos ver dónde iba a comprar los dulces.",
  ui_story_5034_50340301_6_dialog_content = "Te seguimos hasta aquí y vimos lo duro que trabajaste por esa bolsa de dulces.",
  ui_story_5034_50340301_7_option_content = "¿Puede decirme más sobre esta \"deuda\"?",
  ui_story_5034_50340301_8_dialog_content = "Queríamos hacer lo mismo que usted, Sr. Navegante... Queríamos trabajar duro para ganarnos nuestros dulces también.",
  ui_story_5034_50340301_9_dialog_content = "Pero el trabajo resultó ser mucho más difícil de lo que pensábamos...",
  ui_story_5034_50340301_10_dialog_content = "Me pusieron a cargo de las mercancías de la tienda. Mi trabajo consistía en llevar cosas del almacén a la tienda y luego organizarlas en los estantes.",
  ui_story_5034_50340301_11_dialog_content = "Pero el tendero me dijo que no tenía permitido arrastrar las cajas por el suelo, porque de lo contrario su mercancía se dañaría.",
  ui_story_5034_50340301_12_dialog_content = "No tuve más remedio que intentar cargar cada caja, pero las cosas dentro eran tan pesadas...",
  ui_story_5034_50340301_13_dialog_content = "Así que cada vez que se me caía una caja, la añadía a mi deuda... Dijo que era para compensar mis errores en el trabajo.",
  ui_story_5034_50340301_14_dialog_content = "¡Pero revisé las cosas dentro de las cajas y estaban todas bien!",
  ui_story_5034_50340301_15_option_content = "¿Qué estabas haciendo afuera hace un momento, Latan?",
  ui_story_5034_50340301_16_dialog_content = "El tendero dijo que, como soy tan lindo, debería salir y vender anteojos de sol a la gente que pasara por la tienda.",
  ui_story_5034_50340301_17_dialog_content = "Pero nadie se detiene a escucharme...",
  ui_story_5034_50340301_18_dialog_content = "Excepto por ese tipo de aspecto enojado. Es el único que se detuvo a escuchar...",
  ui_story_5034_50340301_19_dialog_content = "Pero él seguía enojándose más y más... y yo estaba tan asustada...",
  ui_story_5034_50340301_19X1_dialog_content = "Eso es todo. Lo siento, PlayerName.",
  ui_story_5034_50340301_20_dialog_content = "Creo que ahora entiendo. Una última pregunta...",
  ui_story_5034_50340301_21_option_content = "¿Por qué querían trabajar por dulces?",
  ui_story_5034_50340301_22_dialog_content = "Si me estabas siguiendo todo el tiempo, entonces debes haber sabido que ya compré los dulces.",
  ui_story_5034_50340301_23_dialog_content = "¿Por qué querías trabajar por más?",
  ui_story_5034_50340301_24_dialog_content = "Bueno... Después de ver lo duro que trabajaste para comprarnos unos dulces...",
  ui_story_5034_50340301_25_dialog_content = "No queríamos parecer un par de niños egoístas y malcriados.",
  ui_story_5034_50340301_26_dialog_content = "Así que decidimos trabajar duro para poder compartir nuestras ganancias contigo y Pollux, porque ella siempre nos cuida.",
  ui_story_5034_50340301_27_dialog_content = "Pólux nos contó una vez la historia de cómo una monja la cuidó en el pasado.",
  ui_story_5034_50340301_28_dialog_content = "Dijo que una de las razones por las que asumió la responsabilidad de la iglesia y acogió a huérfanos como nosotros... fue para mostrar su gratitud por la amabilidad de esa monja.",
  ui_story_5034_50340301_29_dialog_content = "Recuerdo la expresión de su rostro cuando nos dijo que... Fue tan amable y cálido.",
  ui_story_5034_50340301_30_dialog_content = "Fue entonces cuando decidí que también tenía que ser <color=#FFB400>alguien que comprendiera la gratitud</color>.",
  ui_story_5034_50340301_31_dialog_content = "Alguien agradecida y cálida, como ella.",
  ui_story_5034_50340301_32_dialog_content = "Yo también quiero ser así... Para que los demás se sientan cálidos, como Pólux y tú.",
  ui_story_5034_50340301_33_dialog_content = "Pero parece que todo lo que hemos hecho es arruinar las cosas...",
  ui_story_5034_50340301_34_dialog_content = "Comprendo.",
  ui_story_5034_50340301_35_dialog_content = "Jugar trucos tan sucios a niños inocentes como este...",
  ui_story_5034_50340301_36_dialog_content = "¿Así es como vuelan las cosas en Euphoria?",
  ui_story_5034_50340301_37_dialog_content = "Simplemente estaba tratando de enseñarles a asumir la responsabilidad de las consecuencias de sus elecciones.",
  ui_story_5034_50340301_38_dialog_content = "Si lo piensas bien, la deuda que me deben es como la matrícula de mi lección.",
  ui_story_5034_50340301_39_dialog_content = "*sollozando* PlayerName... Tengo miedo... Quiero volver a la iglesia...",
  ui_story_5034_50340301_40_dialog_content = "(Olvídalo. No tiene sentido tratar de razonar con este desvergonzado comerciante).",
  ui_story_5034_50340301_41_dialog_content = "(Necesito encontrar una manera de sacar a estos niños de aquí primero. Incluso si quiero vengarme de ese tipo, primero debería discutirlo con Corax).",
  ui_story_5034_50340301_42_dialog_content = "(Estoy solo en este momento, así que es mejor si no empiezo nada).",
  ui_story_5034_50340301_43_dialog_content = "Estos niños solo querían comprar dos bolsas de dulces. pagaré por ello.",
  ui_story_5034_50340301_44_dialog_content = "Solo dales los dulces y déjalos ir. Resolveré el resto de sus deudas en su lugar.",
  ui_story_5034_50340301_45_dialog_content = "¿Ya olvidaste lo que pasó esta mañana, amigo mío?",
  ui_story_5034_50340301_46_dialog_content = "¿Estás seguro de que puedes pagar este dulce?",
  ui_story_5034_50340301_47_dialog_content = "Heh, tienes algo de valor para mencionar eso. Por supuesto que no lo he olvidado.",
  ui_story_5034_50340301_48_dialog_content = "Además, ¡encontré esto impreso en la bolsa!",
  ui_story_5034_50340301_49_dialog_content = "¡No solo está vendiendo productos falsificados, sino que también está cobrando cien veces más que el precio minorista sugerido! ¡Todavía no he ajustado cuentas contigo sobre eso!",
  ui_story_5034_50340301_50_dialog_content = "¡Jajaja! ¿Y qué si te enteras? No recuerdo haber dicho que mis productos fueran auténticos, ¿verdad?",
  ui_story_5034_50340301_51_dialog_content = "Además, esta es mi tienda, y se me permite establecer los precios como mejor me parezca.",
  ui_story_5034_50340301_52_dialog_content = "En cuanto a nuestra transacción, usted estaba dispuesto a comprar y yo estaba dispuesto a vender... Así es como funciona el negocio, ¿no le parece?",
  ui_story_5034_50340301_53_dialog_content = "Olvidémonos de los dulces, PlayerName...",
  ui_story_5034_50340301_54_dialog_content = "Oh, no hay vuelta atrás en tu palabra ahora. Pediste dos bolsas y ahora tienes que pagarlas.",
  ui_story_5034_50340301_55_dialog_content = "¡Deja de asustar a los niños ya! Te dije que iba a pagar por ellos.",
  ui_story_5034_50340301_56_dialog_content = "Lo haremos como esta mañana. Trabajaré por ambas bolsas de dulces.",
  ui_story_5034_50340301_57_dialog_content = "Muy bien, pero tendrás que trabajar el doble que esta mañana.",
  ui_story_5034_50340301_58_dialog_content = "En cuanto a los niños, deben quedarse aquí hasta que hayas terminado tu trabajo.",
  ui_story_5034_50340301_59_dialog_content = "No voy a arriesgarme a que huyáis cuando mi cabeza está vuelta.",
  ui_story_5034_50340301_60_dialog_content = "Permítanos ayudarlo, Sr. Navegante.",
  ui_story_5034_50340301_61_dialog_content = "Estaré bien, Schewe. Ustedes dos pueden sentarse allí y mirar. Ya hice esto una vez, así que no hay necesidad de preocuparse.",
  ui_story_5034_50340301_62_dialog_content = "Ah, y aquí está la bolsa de dulces que te prometí antes. Puedes comerlo mientras me esperas, ¿de acuerdo?",
  ui_story_5034_50340301_63_dialog_content = "Confía en mí, terminaré antes de que te des cuenta, ¡y estaremos de vuelta en la iglesia en poco tiempo!",
  ui_story_5034_50340302_1_dialog_content = "(Gracias a mi experiencia de la mañana, estoy totalmente familiarizado con el trabajo).",
  ui_story_5034_50340302_2_dialog_content = "(¡Como resultado, pude hacer el doble de trabajo en solo la mitad del tiempo!)",
  ui_story_5034_50340302_3_dialog_content = "(Supongo que todo está en un día de trabajo para mí como el corredor de recados número uno de Astra... Jejeje...)",
  ui_story_5034_50340302_4_dialog_content = "¿Terminó tan pronto? Supongo que me equivoqué al subestimarte, después de todo.",
  ui_story_5034_50340302_5_dialog_content = "Basta de charlas triviales. Solo dales a los niños sus dulces y déjalos ir.",
  ui_story_5034_50340302_6_dialog_content = "No hay necesidad de ser grosero. Espera aquí, yo iré a buscarlo.",
  ui_story_5034_50340302_7_dialog_content = "Dios mío, mis condolencias, amigo.",
  ui_story_5034_50340302_8_dialog_content = "Acabo de revisar mis estantes, y parece que todos los dulces se agotaron.",
  ui_story_5034_50340302_9_dialog_content = "¿Qué? ¿Por qué no nos dijiste antes? ¡¿Cuál fue el punto de todo ese trabajo que hice hace un momento?!",
  ui_story_5034_50340302_10_dialog_content = "Una vez más, no hay necesidad de ser grosero. Trabajaste para mí dos veces en un día. Suena como si estuviera preordenado por el destino, si lo digo yo mismo.",
  ui_story_5034_50340302_11_dialog_content = "Además, nunca soñaría con explotar a mis trabajadores como otros empleadores mezquinos.",
  ui_story_5034_50340302_12_dialog_content = "¿Qué tal si te pago en Nightium por esas dos bolsas de dulces? ¿Es eso justo?",
  ui_story_5034_50340302_13_dialog_content = "(Bueno, ya pude comprarles dulces a los niños...)",
  ui_story_5034_50340302_14_dialog_content = "(Si acepto la sugerencia del comerciante, eso significa que me debe 6000 Nightium).",
  ui_story_5034_50340302_15_dialog_content = "(Eso debería ser más que suficiente para que le compren a Pollux algo más como regalo).",
  ui_story_5034_50340302_16_dialog_content = "Está bien, aceptaré tu oferta.",
  ui_story_5034_50340302_17_dialog_content = "¡Gracias por su comprensión! Dame un momento y volveré con tu paga.",
  ui_story_5034_50340302_18_dialog_content = "Muy bien, aquí está. ¡Gracias de nuevo por su arduo trabajo!",
  ui_story_5034_50340302_19_dialog_content = "10, 20, 30... Espera, ¡esto es solo 60 Nightium!",
  ui_story_5034_50340302_20_dialog_content = "¿A qué estás jugando aquí? ¿No deberían ser 6000 Nightium?",
  ui_story_5034_50340302_21_dialog_content = "No hay error, mi amigo. Cada bolsa vale 30 Nightium, por lo que dos bolsas serían 60 Nightium en total.",
  ui_story_5034_50340302_22_dialog_content = "Incluso esos dos niños podrían hacer los cálculos fácilmente.",
  ui_story_5034_50340302_23_dialog_content = "¡Pero cada bolsa valía 3000 Nightium, no 30!",
  ui_story_5034_50340302_24_dialog_content = "Ah... Olvidas las cosas tan fácilmente, amigo mío.",
  ui_story_5034_50340302_25_dialog_content = "Tú fuiste quien me dijo que cada bolsa solo valía 30 Nightium, ¿sabes?",
  ui_story_5034_50340302_26_dialog_content = "¿Ver? En caso de que lo hayas olvidado, está impreso aquí en la bolsa.",
  ui_story_5034_50340302_27_dialog_content = "¡¿Cómo puedes ser tan desvergonzado?!",
  ui_story_5034_50340302_28_dialog_content = "Hmph... Pensaría que después de pasar casi un día entero aquí, al menos tendrías alguna idea de las reglas de Euphoria.",
  ui_story_5034_50340302_29_dialog_content = "Reglas, reglas, reglas... ¡No quiero volver a oír hablar de las \"reglas de Euphoria\"!",
  ui_story_5034_50340302_30_dialog_content = "Tú siempre eres el que se beneficia, ¿de quién son estas reglas?",
  ui_story_5034_50340302_31_dialog_content = "¡Jajaja! ¿Estás por fin empezando a entender, mi joven amigo?",
  ui_story_5034_50340302_32_dialog_content = "Por supuesto que siempre estoy del lado ganador... Porque los que no tienen dinero ni influencia aquí no dictan las reglas.",
  ui_story_5034_50340302_33_dialog_content = "He terminado de hablar de esto contigo... Schewe, Latan, vámonos de aquí.",
  ui_story_5034_50340302_34_dialog_content = "¿Schewe?",
  ui_story_5034_50340302_35_dialog_content = "¿Latán?",
  ui_story_5034_50340302_36_dialog_content = "¡¿Dónde fuiste?!",
  ui_story_5034_50340302_37_dialog_content = "¿Y adónde crees que vas? Todavía está el asunto de su deuda, ¿sabes?",
  ui_story_5034_50340302_38_dialog_content = "¿Dónde escondes a los niños? ¡Será mejor que no les hagas nada!",
  ui_story_5034_50340302_39_dialog_content = "Lo que decida hacer con ellos depende enteramente de ti, amigo mío.",
  ui_story_5034_50340302_40_dialog_content = "Tú...",
  ui_story_5034_50340401_1_dialog_content = "¿Qué necesito hacer exactamente para que dejes ir a esos dos?",
  ui_story_5034_50340401_2_dialog_content = "No soy más que un simple comerciante con demandas simples. Todo lo que pido es que pague su deuda.",
  ui_story_5034_50340401_3_dialog_content = "¡Pero usted compensó completamente esa deuda!",
  ui_story_5034_50340401_4_dialog_content = "Bueno, si no estás dispuesto a pagarlo, puedes olvidarte de irte de aquí con esos dos niños.",
  ui_story_5034_50340401_5_dialog_content = "Bastardo...!",
  ui_story_5034_50340401_6_dialog_content = "(Espera... ¿Se está acercando a mí o siento Eclipsitas cerca?)",
  ui_story_5034_50340401_7_dialog_content = "(¡Allí! ¡Las cortinas detrás del comerciante! ¡Ahí es donde se esconden!)",
  ui_story_5034_50340401_8_dialog_content = "(No debería estar tan sereno si aparecen Eclipsites en su tienda).",
  ui_story_5034_50340401_9_dialog_content = "(A no ser que...)",
  ui_story_5034_50340401_10_dialog_content = "¿Estás... escondiendo eclipses en tu tienda?",
  ui_story_5034_50340401_11_dialog_content = "No sirve de nada mentir. Ya he sentido su presencia.",
  ui_story_5034_50340401_12_dialog_content = "¿Vaya? Así que eres el Caelestite del que todo el mundo habla.",
  ui_story_5034_50340401_13_dialog_content = "Bueno, como ya has descubierto eso, supongo que no hay nada de malo en mostrártelo.",
  ui_story_5034_50340401_14_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5034_50340401_15_dialog_content = "T-Tú... ¡¿Cómo pudiste mantener a los niños encerrados con Eclipsites?!",
  ui_story_5034_50340401_16_dialog_content = "¡¡¡Waaaah!!!",
  ui_story_5034_50340401_17_dialog_content = "¡Señor Navegante! ¡S-Sálvame...!",
  ui_story_5034_50340401_18_dialog_content = "¡D-Dijo que si hacíamos algún ruido, les diría a los Eclipsites que nos comieran...!",
  ui_story_5034_50340401_19_dialog_content = "Ya es suficiente, Latán. No más llanto...",
  ui_story_5034_50340401_20_dialog_content = "Ya le hemos causado suficientes problemas al Sr. Navegante...",
  ui_story_5034_50340401_21_dialog_content = "¡Nada de esto es culpa de tus muchachos! Es mi culpa por hacer todas esas promesas esta mañana.",
  ui_story_5034_50340401_22_dialog_content = "¡No te preocupes! Me aseguraré de llevarte a casa, sano y salvo.",
  ui_story_5034_50340401_23_dialog_content = "Ah... Haciendo aún más promesas, ¿ya veo?",
  ui_story_5034_50340401_24_dialog_content = "Bastardo... ¡¿Estás dispuesto a deshacerte de tu humanidad, todo por un poco de dinero?!",
  ui_story_5034_50340401_25_dialog_content = "Jajajaja! ¿No crees que es divertido estar hablando de cosas como \"humanidad\" y \"decencia\" en Euforia de todos los lugares?",
  ui_story_5034_50340401_26_dialog_content = "Además, ya te he dicho lo que hay que hacer para rescatarlos. No soy completamente cruel, ¿sabes?",
  ui_story_5034_50340401_27_dialog_content = "Puedes guardarlos... o no. Tu elección.",
  ui_story_5034_50340401_28_dialog_content = "(¡Por supuesto que tengo que salvarlos, pero no puedo seguir dejando que este tipo tenga la ventaja!)",
  ui_story_5034_50340401_29_dialog_content = "(La cuerda que ata sus manos está unida al cuello de los Eclipsites).",
  ui_story_5034_50340401_30_dialog_content = "(Si quiero rescatarlos, también tendré que deshacer la cuerda alrededor de los eclipses).",
  ui_story_5034_50340401_31_dialog_content = "(Parece que tendré que arriesgarme. Préstame un poco de tu suerte, Casta...)",
  ui_story_5034_50340401_32_dialog_content = "¡He tomado mi decisión!",
  ui_story_5034_50340401_33_dialog_content = "¿Muy pronto? Muy bien, ahora vamos a ver si es el correcto.",
  ui_story_5034_50340401_34_dialog_content = "He decidido...",
  ui_story_5034_50340401_35_dialog_content = "¡Para hacer esto!",
  ui_story_5034_50340401_36_dialog_content = "¡Argh! Tú... ¡¿Acabas de tirarme una piedra?! Mi ojo...!",
  ui_story_5034_50340401_37_dialog_content = "¡Te lo merecías!",
  ui_story_5034_50340401_38_dialog_content = "(Menos mal que no me lo comí. Corax no estaba bromeando cuando dijo que estaba un poco rancio).",
  ui_story_5034_50340401_39_dialog_content = "(¡No importa, no hay tiempo que perder! ¡Tengo que salvar a los niños!)",
  ui_story_5034_50340401_40_dialog_content = "¡Señor Navegante!",
  ui_story_5034_50340401_41_dialog_content = "¡Sabía que nos salvarías!",
  ui_story_5034_50340401_42_dialog_content = "¡Escuchen, ustedes dos! ¡Tan pronto como deshaga esta cuerda, debe huir lo más rápido que pueda!",
  ui_story_5034_50340401_43_dialog_content = "Y no vuelvas atrás por ningún motivo, ¿entendido?",
  ui_story_5034_50340401_44_dialog_content = "¿Pero qué hay de ti?",
  ui_story_5034_50340401_45_dialog_content = "Usó la misma cuerda para atarte a ti y a los Eclipsites. Para desatarte, también tendré que liberar a los Eclipsites.",
  ui_story_5034_50340401_46_dialog_content = "Una vez que lo haga, llamaré su atención y correré en la dirección opuesta. ¡No te preocupes por mí, estaré bien!",
  ui_story_5034_50340401_47_dialog_content = "Sr. Navegante...",
  ui_story_5034_50340401_48_dialog_content = "Muy bien, no tenemos tiempo que perder. A la cuenta de tres, ustedes corren lo más rápido que pueden, ¿entendido?",
  ui_story_5034_50340401_49_dialog_content = "Uno...",
  ui_story_5034_50340401_50_dialog_content = "Dos...",
  ui_story_5034_50340401_51_dialog_content = "Tres!",
  ui_story_5034_50340401_52_dialog_content = "<size=45>¡Corre!</size>",
  ui_story_5034_50340402_1_dialog_content = "Grr... Graah...",
  ui_story_5034_50340402_2_dialog_content = "Graah...",
  ui_story_5034_50340402_3_dialog_content = "Urgh... No puedo seguir dejando que me persigan así. Me voy a cansar eventualmente...",
  ui_story_5034_50340402_4_dialog_content = "Necesito pensar en un plan para quitármelos de encima, ¡y rápido!",
  ui_story_5034_50340402_5_dialog_content = "Espera... ¡Si no recuerdo mal, esa calle de más adelante es la que tomamos Corax y yo para entrar en la ciudad!",
  ui_story_5034_50340402_6_dialog_content = "¡Creo que tengo una idea!",
  ui_story_5034_50340402_7_dialog_content = "¡Oye, patán! Dijiste que el <color=#FFB400>destino</color> sigue uniéndonos, ¿verdad? Bueno, ¡de vuelta a ti!",
  ui_story_5034_50340402_8_dialog_content = "Graah!!",
  ui_story_5034_50340402_9_dialog_content = "Graaah!!",
  ui_story_5034_50340402_10_dialog_content = "Mocoso, ¿te estás escondiendo detrás de mí con Eclipsites en tu cola?",
  ui_story_5034_50340402_11_dialog_content = "La costa está clara. Puedes salir ahora.",
  ui_story_5034_50340402_12_dialog_content = "Wow, realmente los eliminaste a todos... ¡No eres tan malo, grandote!",
  ui_story_5034_50340402_13_dialog_content = "Nos encontremos de nuevo. No puedes enfrentarme como un hombre de verdad, ¿así que recurres a este tipo de trucos sucios?",
  ui_story_5034_50340402_14_dialog_content = "¡N-No, eso no es todo! De todos modos, tengo un lugar donde estar ahora mismo, así que... ¡Adiós!",
  ui_story_5034_50340402_15_dialog_content = "¡No puedo agradecerte lo suficiente por tu ayuda, grandote! <color=#FFB400>¡¡Hasta que el destino nos vuelva a unir</color>!!",
  ui_story_5034_50340402_16_dialog_content = "¡Oye! ¡Oye—!",
  ui_story_5034_50340402_17_dialog_content = "Llámame PlayerName! ¡Encuéntrame si alguna vez estás en Eraveil y te mostraré los alrededores!",
  ui_story_5034_50340402_18_dialog_content = "(Gracias a Dios que recordé que la calle estaba llena de matones. ¡Pude usarlos para deshacerme de esos Eclipsites!)",
  ui_story_5034_50340402_19_dialog_content = "(Estoy tan contenta de que todo salió según lo planeado, o de lo contrario me habría metido en un verdadero problema).",
  ui_story_5034_50340402_20_dialog_content = "Extraño... No parece haber nadie dentro de la tienda.",
  ui_story_5034_50340402_21_dialog_content = "El tendero y el resto de sus Eclipsites no se ven por ninguna parte...",
  ui_story_5034_50340402_22_dialog_content = "Oh no... ¿Podrían estar persiguiendo a Schewe y Latan?",
  ui_story_5034_50340402_23_dialog_content = "Esto es malo... Necesito alcanzarlos y—",
  ui_story_5034_50340402_23X1_dialog_content = "<size=45>¡Ay!</size>",
  ui_story_5034_50340402_24_dialog_content = "Jeje, eso dolió...",
  ui_story_5034_50340402_25_dialog_content = "¿Por qué te ves tan agotado? ¿Qué sucedió?",
  ui_story_5034_50340402_26_dialog_content = "¿Y por qué no hay nadie aquí?",
  ui_story_5034_50340402_27_dialog_content = "Casta...? ¿Eres realmente tú?",
  ui_story_5034_50340402_28_dialog_content = "Si, soy yo. ¿Que pasó aquí? ¿Y qué te pasa a ti?",
  ui_story_5034_50340402_29_dialog_content = "Casta! Estoy tan contenta de que estés aquí...",
  ui_story_5034_50340402_30_dialog_content = "Estamos un poco en problemas en este momento. Intentaré hacerlo breve...",
  ui_story_5034_50340402_31_dialog_content = "<color=#e8d9bb>Después de explicarle todo a Casta...</color>",
  ui_story_5034_50340402_32_dialog_content = "Me pareció extraño que la puerta de la tienda estuviera abierta de par en par, por lo que me detuve a echar un vistazo. No tenía idea de todo ese drama.",
  ui_story_5034_50340402_33_dialog_content = "Lo siento mucho, Casta... No pude proteger a Schewe y Latan...",
  ui_story_5034_50340402_34_dialog_content = "Ahora no es el momento de culparse a sí mismo, especialmente en su condición.",
  ui_story_5034_50340402_35_dialog_content = "De todos modos, ya no estás solo. Estoy aqui ahora.",
  ui_story_5034_50340402_36_dialog_content = "Cualquier cosa que se nos presente, podemos encontrar una solución juntos.",
  ui_story_5034_50340402_37_dialog_content = "También sabemos en qué dirección corrieron, así que no te preocupes demasiado.",
  ui_story_5034_50340402_38_dialog_content = "Esto es Euforia, después de todo. No dejaré que les pase nada a esos dos.",
  ui_story_5034_50340402_39_dialog_content = "Gracias, Casta... No sabía que podías ser tan reconfortante.",
  ui_story_5034_50340402_40_dialog_content = "... No tengo idea de lo que estás hablando.",
  ui_story_5034_50340402_41_dialog_content = "Muy bien, ¡vamos! Tenemos que encontrar a esos dos, pase lo que pase.",
  ui_story_5034_50340402_42_dialog_content = "Lidera el camino.",
  ui_story_5034_50340501_1_dialog_content = "Puedo sentir eclipses cerca... Esta calle debería ser.",
  ui_story_5034_50340501_2_dialog_content = "Realmente espero que no les haya pasado nada malo, o de lo contrario yo—",
  ui_story_5034_50340501_3_dialog_content = "Dijiste que vinieron a buscar trabajo, para poder pagarte a ti y a Pólux, ¿verdad?",
  ui_story_5034_50340501_4_dialog_content = "¿Es por eso que te sientes tan responsable de su seguridad?",
  ui_story_5034_50340501_5_dialog_content = "Sí, pero esa no es la única razón... Si no hubiera hecho un montón de promesas idealistas, nada de esto hubiera sucedido.",
  ui_story_5034_50340501_6_dialog_content = "Para empezar, mi bocota es lo que los metió en este lío. Y todo porque querían trabajar duro para comprarme dulces...",
  ui_story_5034_50340501_7_dialog_content = "Así es como son esos dos, para ser honesto.",
  ui_story_5034_50340501_8_dialog_content = "Durante los últimos años, Pollux y yo hemos acogido al menos setenta u ochenta huérfanos aquí en Euphoria.",
  ui_story_5034_50340501_9_dialog_content = "Y aunque la mayoría de ellos tienen personalidades muy distintas, esos dos niños se destacan de una manera inolvidable.",
  ui_story_5034_50340501_10_option_content = "¿Qué quieres decir con \"inolvidable\"?",
  ui_story_5034_50340501_11_dialog_content = "El vínculo entre ellos es increíble.",
  ui_story_5034_50340501_12_dialog_content = "Latan cambió a Schewe para mejor, y Schewe protege a Latan a toda costa. Solo ellos pueden hacer estas cosas el uno por el otro.",
  ui_story_5034_50340501_13_option_content = "Me siento igual.",
  ui_story_5034_50340501_14_dialog_content = "Sabía que lo entenderías.",
  ui_story_5034_50340501_15_dialog_content = "En cualquier caso, son bastante especiales.",
  ui_story_5034_50340501_16_dialog_content = "Si no recuerdo mal, Pollux rescató a Schewe de un garito subterráneo.",
  ui_story_5034_50340501_17_dialog_content = "Cuando llegó por primera vez a la iglesia, se negó a levantar la cabeza o mirar a nadie a los ojos.",
  ui_story_5034_50340501_18_dialog_content = "Y siempre les hablaba a los demás de una manera muy cortés y halagadora, incluso a los niños más pequeños que él.",
  ui_story_5034_50340501_19_dialog_content = "Porque en ese garito, la adulación era la única forma de ganarse la comida y evitar el castigo.",
  ui_story_5034_50340501_20_dialog_content = "Había pasado la mayor parte de su vida viviendo con miedo.",
  ui_story_5034_50340501_21_dialog_content = "Pollux y yo lo intentamos todo, pero no pudimos atravesar los muros que había construido a su alrededor.",
  ui_story_5034_50340501_22_dialog_content = "Entonces, un día, Latan llegó a la iglesia y todo cambió.",
  ui_story_5034_50340501_23_dialog_content = "<color=#e8d9bb>Hace un año</color>",
  ui_story_5034_50340501_24_dialog_content = "*sollozando*",
  ui_story_5034_50340501_25_dialog_content = "¿P-Por qué estás llorando? ¿Es porque hice un mal trabajo envolviendo tus vendajes?",
  ui_story_5034_50340501_26_dialog_content = "Lo siento... No soy bueno con este tipo de cosas...",
  ui_story_5034_50340501_27_dialog_content = "He estado practicando mucho, pero todavía no puedo hacerlo tan bien como Casta...",
  ui_story_5034_50340501_28_dialog_content = "Todo es mi culpa... Por favor, no llores...",
  ui_story_5034_50340501_29_dialog_content = "*Sollozando* Yo... no estoy llorando por eso...",
  ui_story_5034_50340501_30_dialog_content = "Es por ese tipo con la cicatriz en la cara...",
  ui_story_5034_50340501_31_dialog_content = "Dijo que tuvo que cortarme el pelo para poder coserme la herida de la cabeza...",
  ui_story_5034_50340501_32_dialog_content = "¿Un tipo con una cicatriz en la cara? ¿Te refieres a Nekoyashiki?",
  ui_story_5034_50340501_33_dialog_content = "¿Y luego qué pasó? ¿Que te hizo?",
  ui_story_5034_50340501_34_dialog_content = "Entonces... Entonces... ¡Me cortó el flequillo y me dejó así!",
  ui_story_5034_50340501_35_dialog_content = "*Sollozando* Me veo horrible ahora... ¡Waaaaaaah!",
  ui_story_5034_50340501_36_dialog_content = "¿Eh? ¿Eso es todo? ¡Te ves bien! De hecho, si miro más de cerca... *se ríe*",
  ui_story_5034_50340501_37_dialog_content = "¡Ver! ¡Tú también te estás riendo! ¡Lo sabía, parezco un bicho raro! Waaaaaah!",
  ui_story_5034_50340501_38_dialog_content = "¡No eso no es! En todo caso, te ves aún más lindo ahora. ¡En realidad!",
  ui_story_5034_50340501_39_dialog_content = "M-Estás mintiendo... Solo dices eso para hacerme sentir mejor, ¿no?",
  ui_story_5034_50340501_40_dialog_content = "¡¿Qué?! ¡Pero no te estoy mintiendo! Así es como realmente me siento, ¡lo prometo!",
  ui_story_5034_50340501_41_dialog_content = "*olfatear* Lo siento, pero ¿puedo tocar tu cabello por un segundo? Si hago esto, y luego esto...",
  ui_story_5034_50340501_42_dialog_content = "¡Espera aquí, voy a buscar un espejo!",
  ui_story_5034_50340501_43_dialog_content = "¿Bien? ¿Qué piensas?",
  ui_story_5034_50340501_44_dialog_content = "*Sniff*",
  ui_story_5034_50340501_44X1_dialog_content = "Bueno... creo que se ve un poco diferente...",
  ui_story_5034_50340501_45_dialog_content = "Es incluso un poco lindo ahora...",
  ui_story_5034_50340501_45X1_dialog_content = "(E-En realidad no hay diferencia... En realidad no hice nada...)",
  ui_story_5034_50340501_46_dialog_content = "¡Ay! ¿E-Fue raro que dijera eso? ¿Pensarán los demás que soy realmente snob ahora?",
  ui_story_5034_50340501_47_dialog_content = "Aunque, realmente me veo lindo, jejeje...",
  ui_story_5034_50340501_48_dialog_content = "¿Ver? Te dije que no estaba mintiendo.",
  ui_story_5034_50340501_49_dialog_content = "Mi nombre es Latán. ¿Lo que es tuyo?",
  ui_story_5034_50340501_50_dialog_content = "Soy... Schewe.",
  ui_story_5034_50340501_51_dialog_content = "Sche-nosotros!",
  ui_story_5034_50340501_52_dialog_content = "¡Hurra! ¡El nombre de mi nuevo mejor amigo es Sche-we!",
  ui_story_5034_50340501_53_dialog_content = "¿B-Mejor... amigo?",
  ui_story_5034_50340501_54_dialog_content = "¿Quieres decir que no quieres que seamos amigos?",
  ui_story_5034_50340501_55_dialog_content = "¡N-No, por supuesto que quiero que seamos amigos!",
  ui_story_5034_50340501_56_dialog_content = "¡Seré tu mejor amigo y tú también puedes ser mi mejor amigo! ¿De acuerdo?",
  ui_story_5034_50340501_57_dialog_content = "¡De acuerdo!",
  ui_story_5034_50340501_58_dialog_content = "Pensé que a esos dos les gustaba jugar juntos. No tenía idea de que tenían ese tipo de pasado.",
  ui_story_5034_50340501_59_dialog_content = "Solo alguien tan inocente y sincero como Latan podría derribar los muros que rodean el corazón de Schewe... Realmente es una amistad rara.",
  ui_story_5034_50340501_60_dialog_content = "Tienes razón, así que Schewe no dejará que le pase nada a Latan. Es un chico inteligente. No te preocupes demasiado.",
  ui_story_5034_50340501_61_dialog_content = "Sí... Pero aun así, no puedo evitar sentirme un poco preocupado. También...",
  ui_story_5034_50340501_62_dialog_content = "¿También?",
  ui_story_5034_50340501_63_dialog_content = "¡Vigila tu espalda! ¡Hay un eclipse detrás de nosotros!",
  ui_story_5034_50340501_64_dialog_content = "Grr... Graah...",
  ui_story_5034_50340501_65_dialog_content = "Je, mira esto.",
  ui_story_5034_50340501_66_dialog_content = "Graaaaah—",
  ui_story_5034_50340501_67_dialog_content = "Espera, estoy bastante seguro de que este Eclipsite se parece al que estaba dentro de la tienda.",
  ui_story_5034_50340501_68_dialog_content = "Eso significa que estamos en el camino correcto. Esos dos deben haber pasado por aquí en algún momento.",
  ui_story_5034_50340501_69_dialog_content = "¡Casta, sigamos adelante!",
  ui_story_5034_50340501_70_dialog_content = "Entendido.",
  ui_story_5034_50340502_1_dialog_content = "Puedo sentir eclipses cerca... ¿Tal vez persiguieron a los niños por esta calle?",
  ui_story_5034_50340502_2_dialog_content = "Mierda, no esta calle infestada de matones otra vez...",
  ui_story_5034_50340502_3_dialog_content = "Relájate, no te pondrán un dedo encima mientras yo esté aquí.",
  ui_story_5034_50340502_4_dialog_content = "¿Bien? ¿Todavía puedes sentir algún eclipse o decir en qué dirección se fueron?",
  ui_story_5034_50340502_5_dialog_content = "ya no los siento...",
  ui_story_5034_50340502_6_dialog_content = "Pero si pasaron por aquí, es posible que fueran eliminados por estos matones callejeros, ¿verdad?",
  ui_story_5034_50340502_7_dialog_content = "¿Entonces que debemos hacer ahora? Esa fue nuestra única pista...",
  ui_story_5034_50340502_8_dialog_content = "No te preocupes, con toda esta gente alrededor, estoy seguro de que alguien debe haber visto a esos dos.",
  ui_story_5034_50340502_9_dialog_content = "Separémonos y preguntemos.",
  ui_story_5034_50340502_10_dialog_content = "Bien...",
  ui_story_5034_50340502_11_dialog_content = "Sé que aún te sientes culpable, pero en este momento nuestra máxima prioridad es encontrar a los niños.",
  ui_story_5034_50340502_12_dialog_content = "Estás bien. Tenemos que darnos prisa si queremos salvarlos.",
  ui_story_5034_50340502_13_dialog_content = "Iré a preguntar por ahí. Encontrémonos aquí una vez que sepamos más.",
  ui_story_5034_50340502_14_dialog_content = "Suena bien.",
  ui_story_5034_50340502_15_dialog_content = "¿eh? ¡No tu otra vez!",
  ui_story_5034_50340502_16_dialog_content = "Vaya, eres como una mosca molesta que no para de zumbar alrededor de mi cabeza. ¿Qué haces aquí otra vez?",
  ui_story_5034_50340502_17_dialog_content = "¡Ay, grandullón! ¡Gracias a Dios que todavía estás aquí!",
  ui_story_5034_50340502_18_dialog_content = "Además, ¿no te dije mi nombre? Su-",
  ui_story_5034_50340502_19_dialog_content = "PlayerName, ¿Correcto? No lo olvidé, ¡ahora date prisa y dime lo que quieres!",
  ui_story_5034_50340502_20_dialog_content = "¿Recuerdas a esa niña de hoy? ¿El que intentó venderte un par de gafas de sol?",
  ui_story_5034_50340502_21_dialog_content = "¿La has visto por aquí?",
  ui_story_5034_50340502_22_dialog_content = "¿Qué, ese mocoso? Sí, la vi hace un tiempo.",
  ui_story_5034_50340502_23_dialog_content = "Ella salió corriendo en esa dirección con otro niño pequeño.",
  ui_story_5034_50340502_24_dialog_content = "¡Eres un salvavidas, grandote! Deberías pensar en abrir un Odd Jobs aquí en Euphoria, ¿sabes?",
  ui_story_5034_50340502_25_dialog_content = "¡Tengo que irme ahora! ¡Gracias de nuevo!",
  ui_story_5034_50340502_26_dialog_content = "¿Qué? Oye-",
  ui_story_5034_50340502_27_dialog_content = "El se fue. Maldito punk...",
  ui_story_5034_50340502_28_dialog_content = "*Se aclara la garganta* \n<size=45>¡Si alguna vez quieres quedarte en Euphoria, te aceptaré como mi hermanito!</size>",
  ui_story_5034_50340502_29_dialog_content = "<size=45>¡Me parece bien!</size>",
  ui_story_5034_50340502_30_dialog_content = "<size=45>¡Excepto que puedo ser el hermano mayor!</size>",
  ui_story_5034_50340502_31_dialog_content = "Casta! ¡Sé en qué dirección se fueron!",
  ui_story_5034_50340502_32_dialog_content = "Genial, entonces vamos.",
  ui_story_5034_50340502_33_dialog_content = "¡De acuerdo!",
  ui_story_5034_50340601_1_dialog_content = "¿Mmm? Qué es esto...",
  ui_story_5034_50340601_2_dialog_content = "Espera, ¿cómo llegó tan lejos ya?",
  ui_story_5034_50340601_3_dialog_content = "No es demasiado tarde. Todavía puedo hacerlo...",
  ui_story_5034_50340601_4_dialog_content = "¡Espera un minuto!",
  ui_story_5034_50340601_5_dialog_content = "Latan, Schewe, no dejaré que les pase nada...",
  ui_story_5034_50340601_6_dialog_content = "<size=45>¡¡Te dije que esperaras!!</size>",
  ui_story_5034_50340601_7_dialog_content = "¡No tenemos tiempo que perder, Casta! Si no nos damos prisa—",
  ui_story_5034_50340601_8_dialog_content = "¿Podrías simplemente calmarte por un segundo? ¡Mira esto!",
  ui_story_5034_50340601_9_dialog_content = "Esto es... ¡Estos son los dulces que les di!",
  ui_story_5034_50340601_10_dialog_content = "¡Y mira! ¡Aquí hay más!",
  ui_story_5034_50340601_11_dialog_content = "Parece que estaban dejando caer caramelos mientras corrían. ¿Quizás estaban dejando un rastro para que lo siguiéramos?",
  ui_story_5034_50340601_12_dialog_content = "Bueno, no importa si lo estaban haciendo intencionalmente o no.",
  ui_story_5034_50340601_13_dialog_content = "Mientras sigamos el rastro de los dulces, estoy seguro de que los encontraremos en poco tiempo.",
  ui_story_5034_50340601_14_dialog_content = "Tienes toda la razón. Lo siento por perder la compostura.",
  ui_story_5034_50340601_15_dialog_content = "Qué bueno que estuvieras aquí para ver los dulces. ¡Ahora démonos prisa y sigamos el rastro!",
  ui_story_5034_50340601_16_dialog_content = "Ahora espera un segundo. Puede que no tengamos que tener tanta prisa, después de todo.",
  ui_story_5034_50340601_17_dialog_content = "Si eligieran correr por esta calle, solo puedo pensar en un lugar al que irían.",
  ui_story_5034_50340601_18_dialog_content = "¿Estás diciendo que ya sabes dónde están?",
  ui_story_5034_50340601_19_dialog_content = "La Iglesia.",
  ui_story_5034_50340601_20_dialog_content = "Una de las primeras cosas que les enseñamos a los niños es que regresen directamente a la iglesia si alguna vez se encuentran en problemas.",
  ui_story_5034_50340601_21_dialog_content = "Pero aun así, existe la posibilidad de que se encuentren con Eclipsites en el camino. ¡Aún no podemos relajarnos!",
  ui_story_5034_50340601_22_dialog_content = "Estoy tan preocupado por su seguridad como tú, si no más. Pero no quiero que entres en pánico más de lo que ya tienes.",
  ui_story_5034_50340601_23_dialog_content = "Además... confío en ella.",
  ui_story_5034_50340601_24_dialog_content = "Mientras lleguen cerca de la iglesia, estoy seguro de que no permitirá que les pase nada.",
  ui_story_5034_50340601_25_dialog_content = "Ahora pongámonos en movimiento. Regresaremos a la <color=#FFB400>iglesia</color>.",
  ui_story_5034_50340601_26_dialog_content = "¿Por qué la entrada de la iglesia está rodeada de eclipses? ¿A menos que el tendero los persiguiera hasta aquí?",
  ui_story_5034_50340601_27_dialog_content = "¡Vamos a sacarlos, Casta! ¡Te guiaré, y estos Eclipsites no tendrán ninguna posibilidad contra nosotros!",
  ui_story_5034_50340601_28_dialog_content = "Me encantaría pero...",
  ui_story_5034_50340601_29_dialog_content = "<color=#e8d9bb>¡Bang! ¡Bang!</color>",
  ui_story_5034_50340601_30_dialog_content = "Creo que esta pelea le pertenece a otra persona ahora.",
  ui_story_5034_50340601_31_dialog_content = "¿Son estos los monstruos que los persiguieron a ustedes dos hasta aquí?",
  ui_story_5034_50340601_32_dialog_content = "Ya no hay nada de qué preocuparse. Latan, Schewe, ahora estáis a salvo.",
  ui_story_5034_50340601_33_dialog_content = "Pólux... Te prometo que no volveré a escapar así...",
  ui_story_5034_50340601_34_dialog_content = "E-Todo fue mi culpa...",
  ui_story_5034_50340601_35_dialog_content = "Ya te has disculpado, ¿no? Lo más importante es que ustedes dos están de vuelta, sanos y salvos.",
  ui_story_5034_50340601_36_dialog_content = "Vamos... No más lágrimas, ¿de acuerdo?",
  ui_story_5034_50340601_37_dialog_content = "¡Es Pólux! ¡Y los niños también! Estoy tan contenta de que estén a salvo.",
  ui_story_5034_50340601_38_dialog_content = "¿Crees que finalmente puedes dejar de preocuparte ahora?",
  ui_story_5034_50340601_39_dialog_content = "Toma, esto es para ti.",
  ui_story_5034_50340601_40_dialog_content = "Casta... ¿Recogiste todos los dulces que vimos en el camino de regreso?",
  ui_story_5034_50340601_41_dialog_content = "Parecías tener demasiada prisa para hacerles caso.",
  ui_story_5034_50340601_42_dialog_content = "¿Usted y los niños no trabajaron duro para este dulce? Toma, ahora puedes dárselo.",
  ui_story_5034_50340601_43_dialog_content = "¡Gracias! ¡Muchas gracias, Casta!",
  ui_story_5034_50340601_44_dialog_content = "Si tan solo te gustaran los dulces también... De esa manera, podría darte algunos como mi forma de decir gracias.",
  ui_story_5034_50340601_45_dialog_content = "Como si alguna vez disfrutaría comiendo algo tan infantil como los dulces.",
  ui_story_5034_50340601_46_dialog_content = "¡Maldita sea todo! ¡Estos eclipses sin cerebro no entienden una palabra de lo que digo!",
  ui_story_5034_50340601_47_dialog_content = "¡¿Cómo pudieron perseguir a esos dos hasta aquí?!",
  ui_story_5034_50340601_48_dialog_content = "Puedo soportar perder dinero y mercancías, pero si esas dos mujeres de Raven's Blood se enteran de esto...",
  ui_story_5034_50340601_49_dialog_content = "Grr... Graah...",
  ui_story_5034_50340601_50_dialog_content = "G-¡Aléjate de mí!",
  ui_story_5034_50340601_51_dialog_content = "Oye... ¡Es el tendero!",
  ui_story_5034_50340601_52_dialog_content = "¡Cómo te atreves a mostrar tu cara por aquí! ¡No voy a dejar que te escapes esta vez!",
  ui_story_5034_50340601_53_dialog_content = "Graaaaah—",
  ui_story_5034_50340601_54_dialog_content = "¡Aaaaaahhh! ¡¡Alguien me salve!!",
  ui_story_5034_50340601_55_dialog_content = "¿Salvarte? ¡Tú eres el que trajo todos estos eclipses aquí en primer lugar! Hiciste tu cama, ¡ahora duerme en ella!",
  ui_story_5034_50340601_56_dialog_content = "¡Yo... estaba equivocado! ¡Lo siento! ¡Te lo ruego, por favor ayúdame!",
  ui_story_5034_50340601_57_dialog_content = "¡Haré lo que quieras, pero por favor no dejes que me coman vivo!",
  ui_story_5034_50340601_58_dialog_content = "Vengar a los niños sería mucho mejor si lo hiciéramos nosotros mismos, ¿no le parece?",
  ui_story_5034_50340601_59_dialog_content = "Tienes toda la razón, Casta.",
  ui_story_5034_50340601_60_dialog_content = "Yo digo que lo rescatemos de los Eclipsites. De esa manera, podemos hacer que nos devuelva el dinero completo... con intereses.",
  ui_story_5034_50340602_1_dialog_content = "¿A alguien le importaría decirme qué diablos está pasando aquí?",
  ui_story_5034_50340602_2_dialog_content = "Lo siento, Pólux. Todo esto fue mi culpa.",
  ui_story_5034_50340602_3_dialog_content = "Verás, lo que pasó fue...",
  ui_story_5034_50340602_4_dialog_content = "<color=#e8d9bb>Y así, le expliqué todo a Pólux de principio a fin...</color>",
  ui_story_5034_50340602_5_dialog_content = "Bien, ahora entiendo.",
  ui_story_5034_50340602_6_dialog_content = "No somos extraños el uno para el otro. Estoy seguro de que sabe quién está a cargo aquí.",
  ui_story_5034_50340602_7_dialog_content = "P-Pollux... ¡Lo juro, no fue mi intención traer a esos eclipses hasta aquí! YO...",
  ui_story_5034_50340602_8_dialog_content = "A menos que... ¿pensaste que un par de secuaces de Eclipsite serían suficientes para derribarme?",
  ui_story_5034_50340602_9_dialog_content = "¡N-No! te juro que no es eso!!",
  ui_story_5034_50340602_10_dialog_content = "Es solo que no tenía idea de que esos dos mocosos, quiero decir, esos dos valiosos clientes eran de su iglesia...",
  ui_story_5034_50340602_11_dialog_content = "Entonces, ¿lo que estás diciendo es que si solo fueran niños comunes, no habrías tenido problemas para engañarlos o alimentarlos con Eclipsites? ¿Es asi?",
  ui_story_5034_50340602_12_dialog_content = "¡Juro que nunca lo volveré a hacer! ¡Por favor, ahórrate esta única vez!",
  ui_story_5034_50340602_13_dialog_content = "¡Me olvidaré de sus deudas!",
  ui_story_5034_50340602_14_dialog_content = "¡Ah, y su pago! Aquí, ¡este es su pago por toda su ayuda! Si no es suficiente, ¡siempre puedo agregar más!",
  ui_story_5034_50340602_15_dialog_content = "Adelante, Latan y Schewe. Ustedes dos se lo ganaron, así que es suyo para cobrarlo.",
  ui_story_5034_50340602_16_dialog_content = "Me voy, Latán. Espera aquí, ¿de acuerdo?",
  ui_story_5034_50340602_17_dialog_content = "¡Todo está aquí, Pólux! ¡Ni un solo corto de Nightium!",
  ui_story_5034_50340602_18_dialog_content = "Ah, pero seguro que no es suficiente, ¿sí? ¿Qué más puedo ofrecerte? ¿Dulce? ¡Tu puedes tenerlo todo!",
  ui_story_5034_50340602_19_dialog_content = "¡Por favor, déjame volver a mi tienda y te prometo que enviaré a alguien para que te lo entregue en la puerta de tu casa!",
  ui_story_5034_50340602_20_dialog_content = "¿Qué te hace pensar que confiaremos en ti después de todo esto?",
  ui_story_5034_50340602_21_dialog_content = "E incluso si haces lo correcto hoy, ¿quién puede decir que mañana no empezarás a estafar a la gente de nuevo?",
  ui_story_5034_50340602_22_dialog_content = "Ooh, en qué drama me he metido. PlayerName tiene un punto",
  ui_story_5034_50340602_23_dialog_content = "La euforia puede estar lejos de los caminos trillados, pero incluso si todos sus productos son importados, sus precios siguen siendo demasiado exorbitantes, lo que equivale a un monopolio.",
  ui_story_5034_50340602_24_dialog_content = "Lo que es más, los bienes por los que está cobrando un brazo y una pierna ni siquiera son el verdadero negocio.",
  ui_story_5034_50340602_25_dialog_content = "Nekoyashiki, bastante hipócrita, ¿no?",
  ui_story_5034_50340602_26_dialog_content = "¿No es así como haces tu dinero también? La única diferencia es que tú vendes información y yo vendo mercadería.",
  ui_story_5034_50340602_27_dialog_content = "No te sientes culpable por nada de esto, ¿verdad?",
  ui_story_5034_50340602_28_dialog_content = "¡¿N-No acepté ya darte mi dinero y dulces a cambio de mi seguridad?!",
  ui_story_5034_50340602_29_dialog_content = "¡¿Que mas quieres de mi?!",
  ui_story_5034_50340602_30_dialog_content = "Bueno, ya que preguntas... De hecho, tengo una idea. Si Pollux está de acuerdo, te perdonaremos.",
  ui_story_5034_50340602_31_dialog_content = "Escuchemos tu idea, entonces.",
  ui_story_5034_50340602_32_dialog_content = "No queremos nada de su dinero sucio. Puedes quedártelo todo para ti.",
  ui_story_5034_50340602_33_dialog_content = "Pero tienes que entregar tu tienda y dejar que Nekoyashiki se haga cargo como su nuevo propietario.",
  ui_story_5034_50340602_34_dialog_content = "Dado que no podemos garantizar que cambiará sus formas, lo menos que podemos hacer es quitarle su tienda y dejarla con alguien que no confíe en este tipo de trucos para ganar dinero.",
  ui_story_5034_50340602_35_dialog_content = "Además, estoy seguro de que tienes suficiente dinero para salir de la ciudad y probar suerte en Umbraton, ¿verdad?",
  ui_story_5034_50340602_36_dialog_content = "Estoy seguro de que los comerciantes estarán más que felices de mostrarle cómo <color=#FFB400>hacer negocios de la manera correcta</color>.",
  ui_story_5034_50340602_37_dialog_content = "Pero tomar mi tienda es demasiado, ¿no crees...?",
  ui_story_5034_50340602_38_dialog_content = "Pensé que habías dicho que estabas dispuesto a hacer cualquier cosa. ¿O te estás retractando de tu palabra tan rápido?",
  ui_story_5034_50340602_39_dialog_content = "Argh... Bien. La tienda es toda tuya.",
  ui_story_5034_50340602_40_dialog_content = "Ahora, ¿puedes dejarme ir?",
  ui_story_5034_50340602_41_dialog_content = "No dejes que te pillemos haciendo este tipo de cosas de nuevo, o puede que no tengas tanta suerte la próxima vez. ¿Entender?",
  ui_story_5034_50340602_42_dialog_content = "Ah, y ten cuidado en tu camino de regreso. Algunas de tus \"mascotas\" aún podrían estar deambulando por ahí.",
  ui_story_5034_50340602_43_dialog_content = "... Hmph.",
  ui_story_5034_50340602_44_dialog_content = "Pareces peculiarmente feliz por PlayerNamelas condiciones de",
  ui_story_5034_50340602_45_dialog_content = "Has estado planeando esto, ¿verdad?",
  ui_story_5034_50340602_46_dialog_content = "Nada se te escapa en absoluto.",
  ui_story_5034_50340602_47_dialog_content = "Pero no esperaba que los niños también se involucraran. Eso fue mi culpa por ser descuidado, y lo siento.",
  ui_story_5034_50340602_48_dialog_content = "Me apresuré a regresar tan pronto como escuché lo que sucedió. Menos mal que es bastante inteligente, o de lo contrario los niños podrían haberse metido en más problemas.",
  ui_story_5034_50340602_49_dialog_content = "¿Dónde está él de todos modos?",
  ui_story_5034_50340603_1_dialog_content = "¡Señor Navegante! ¡Estoy tan contenta de que los Eclipsites no te devoraran y escupieran tus huesos!",
  ui_story_5034_50340603_2_dialog_content = "Por supuesto que no... Sé que no quieres decir nada más con eso, pero realmente deberías elegir tus palabras con más cuidado, Latan.",
  ui_story_5034_50340603_3_dialog_content = "De todos modos, ¡ven a echar un vistazo a lo que tengo aquí!",
  ui_story_5034_50340603_4_dialog_content = "¡Son los dulces que dejé atrás!",
  ui_story_5034_50340603_5_dialog_content = "¡Sabía que lo encontraría, Sr. Navegante!",
  ui_story_5034_50340603_6_dialog_content = "¡Eres el mejor, Sr. Navegante!",
  ui_story_5034_50340603_7_dialog_content = "No fui solo yo, ¿sabes? Fue gracias a ustedes y a su pensamiento rápido que pude seguir su rastro y encontrarlos.",
  ui_story_5034_50340603_8_dialog_content = "Aún así, nunca esperé que los recogiera todos y nos los devolviera, Sr. Navegante...",
  ui_story_5034_50340603_9_dialog_content = "Bueno, te importan mucho, ¿no? Toma, llévatelos.",
  ui_story_5034_50340603_10_dialog_content = "Además, Casta fue quien recogió los dulces, no yo. Si alguien merece tu agradecimiento, es ella.",
  ui_story_5034_50340603_11_dialog_content = "Pero Casta odia los dulces, o cualquier cosa dulce para el caso... Solo le gustan las cosas amargas.",
  ui_story_5034_50340603_12_dialog_content = "De todos modos, no es que nos hayamos olvidado de hacerle un regalo a Casta.",
  ui_story_5034_50340603_13_dialog_content = "¿Es eso así? Todavía tengo que agradecerle adecuadamente por ayudarme hoy.",
  ui_story_5034_50340603_14_dialog_content = "Excepto que no tengo idea de dónde se supone que debo encontrar algo amargo para ella...",
  ui_story_5034_50340603_15_dialog_content = "Entonces, ¿qué le dieron ustedes dos? ¿Quizás pueda tomar prestada algo de inspiración?",
  ui_story_5034_50340603_16_dialog_content = "Oh...",
  ui_story_5034_50340603_17_dialog_content = "Supongo que está bien decírtelo, ya que nos salvaste hoy. Pero es una sorpresa, ¡así que no se lo digas a nadie!",
  ui_story_5034_50340603_18_dialog_content = "Nuestro plan es esperar hasta que no esté mirando... ¡y luego sorprenderla con un gran abrazo de oso!",
  ui_story_5034_50340603_19_dialog_content = "Aunque siempre se queja de que hace demasiado calor cuando la abrazamos...",
  ui_story_5034_50340603_20_dialog_content = "¡La he visto sonreír para sí misma después de cada abrazo!",
  ui_story_5034_50340603_21_dialog_content = "Si usted también quiere agradecerle, Sr. Navegante... ¿por qué no darle un abrazo?",
  ui_story_5034_50340603_22_dialog_content = "Er... Creo que voy a fingir que no escuché nada.",
  ui_story_5034_50340603_23_dialog_content = "¿Cree que a Pólux también le gustarán nuestros dulces, Sr. Navegante?",
  ui_story_5034_50340603_24_dialog_content = "Causamos tantos problemas por unos dulces...",
  ui_story_5034_50340603_25_dialog_content = "Definitivamente. Estoy seguro de que ella lo disfrutará mucho.",
  ui_story_5034_50340603_26_dialog_content = "Si comparten sus cosas favoritas con ella, definitivamente apreciará el gesto.",
  ui_story_5034_50340603_27_dialog_content = "Además, nunca se enojaría contigo por lo que pasó hoy.",
  ui_story_5034_50340603_28_dialog_content = "Lo más importante para ella, y para nosotros, es que ambos estéis sanos y salvos.",
  ui_story_5034_50340603_29_dialog_content = "Solo piénsalo, ¿no se sintió aliviada cuando ustedes dos regresaron a salvo a la iglesia?",
  ui_story_5034_50340603_30_dialog_content = "En todo caso, ustedes deberían estar preocupados por mí, y por lo que ella me va a hacer por causar todo este problema en primer lugar...",
  ui_story_5034_50340603_31_dialog_content = "Aquí, Sr. Navegante. Toma la mitad de mis dulces.",
  ui_story_5034_50340603_32_dialog_content = "¿Ah?",
  ui_story_5034_50340603_33_dialog_content = "Si le das un poco a Pollux, ¡tampoco se enfadará contigo!",
  ui_story_5034_50340603_34_dialog_content = "¡E-Entonces tome la mitad de mis dulces también, Sr. Navegante!",
  ui_story_5034_50340603_35_dialog_content = "¡Ese es un regalo de agradecimiento para usted, Sr. Navegante!",
  ui_story_5034_50340603_36_dialog_content = "¡Jajaja! Muchas gracias chicos. Solo tomaré una pieza de cada uno de ustedes, ¿de acuerdo?",
  ui_story_5034_50340603_37_dialog_content = "¡Apreciaré los dulces que me diste por los siglos de los siglos!",
  ui_story_5034_50340603_38_dialog_content = "Schewe! ¡Latán! PlayerName!",
  ui_story_5034_50340603_39_dialog_content = "La cena está lista, ¡así que date prisa, o no quedará nada para ti!",
  ui_story_5034_50340603_40_dialog_content = "Vamos, ustedes dos. ¡Vamos a tener una comida agradable y merecida!",
  ui_story_5034_50340603_41_dialog_content = "¡De acuerdo!"
}
return config
